-- Friend request notifications. Notification inserts are generated by trusted RPCs.
create or replace function public.send_friend_request(target_user uuid)
returns uuid
language plpgsql
security definer
set search_path to ''
as $function$
declare
  new_request_id uuid;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if target_user is null or target_user = auth.uid() then raise exception 'Invalid user'; end if;
  if not exists (select 1 from public.profiles p where p.id = target_user) then raise exception 'User not found'; end if;
  if exists (select 1 from public.blocked_users b where
    (b.blocker_id = auth.uid() and b.blocked_id = target_user) or
    (b.blocker_id = target_user and b.blocked_id = auth.uid())) then
    raise exception 'This connection is unavailable';
  end if;
  if exists (select 1 from public.friendships f where
    f.user_low_id = least(auth.uid(), target_user) and f.user_high_id = greatest(auth.uid(), target_user)) then
    raise exception 'You are already friends';
  end if;
  if exists (select 1 from public.friend_requests r where r.status='pending' and
    ((r.sender_id=auth.uid() and r.receiver_id=target_user) or
     (r.sender_id=target_user and r.receiver_id=auth.uid()))) then
    raise exception 'A pending request already exists';
  end if;

  insert into public.friend_requests(sender_id, receiver_id, status)
  values(auth.uid(), target_user, 'pending')
  returning id into new_request_id;

  insert into public.notifications(user_id, category, title, body, data)
  values(
    target_user,
    'friend',
    'Friend request',
    'You received a friend request.',
    pg_catalog.jsonb_build_object(
      'type', 'friend_request',
      'from_user_id', auth.uid(),
      'request_id', new_request_id
    )
  );

  return new_request_id;
end;
$function$;

create or replace function public.respond_friend_request(request_id uuid, accept_request boolean)
returns void
language plpgsql
security definer
set search_path to ''
as $function$
declare
  request_row public.friend_requests%rowtype;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;

  select * into request_row from public.friend_requests
    where id=request_id and receiver_id=auth.uid() and status='pending'
    for update;
  if not found then raise exception 'Friend request not found'; end if;

  if exists (select 1 from public.blocked_users b where
    (b.blocker_id=auth.uid() and b.blocked_id=request_row.sender_id) or
    (b.blocker_id=request_row.sender_id and b.blocked_id=auth.uid())) then
    raise exception 'This connection is unavailable';
  end if;

  update public.friend_requests
    set status=case when accept_request then 'accepted' else 'declined' end,
        responded_at=pg_catalog.now()
    where id=request_id;

  if accept_request then
    insert into public.friendships(user_low_id,user_high_id)
    values(least(auth.uid(),request_row.sender_id),greatest(auth.uid(),request_row.sender_id))
    on conflict do nothing;

    insert into public.notifications(user_id, category, title, body, data)
    values(
      request_row.sender_id,
      'friend',
      'Friend request accepted',
      'Your friend request was accepted.',
      pg_catalog.jsonb_build_object(
        'type', 'friend_request_accepted',
        'from_user_id', auth.uid(),
        'request_id', request_row.id
      )
    );
  end if;
end;
$function$;

revoke all on function public.send_friend_request(uuid) from public, anon;
grant execute on function public.send_friend_request(uuid) to authenticated;
revoke all on function public.respond_friend_request(uuid, boolean) from public, anon;
grant execute on function public.respond_friend_request(uuid, boolean) to authenticated;
